// any characters: count by code point
var counts = new Dictionary<int, int>();
s = s.Normalize();                                   // one form for “é”
for (int i = 0; i < s.Length; i++) {
    int cp = char.ConvertToUtf32(s, i);              // surrogate pair → one code point
    if (char.IsSurrogatePair(s, i)) i++;
    counts[cp] = counts.GetValueOrDefault(cp) + 1;   // a new key gives 0 + 1
}

