// Group Shifted Strings: "abc", "bcd", "xyz" → key "abc"
static string ShiftKey(string s) {
    var key = new char[s.Length];
    for (int i = 0; i < s.Length; i++)
        key[i] = (char)('a' + (s[i] - s[0] + 26) % 26);   // shift so the first letter is 'a'
    return new string(key);
}

